scraper_config.css_style:
body { 
                    font-family: Times New Roman, serif; 
                    margin: 5%; 
                    text-align: justify; 
                }
                h1 { 
                    text-align: center; 
                    font-size: 2em;
                    margin: 1em 0 1em 0;
                }
                h2 { margin-top: 1em; }
                h3 { margin-top: 1em; }
                p { margin: 1em 0; }
                .chapter-content {
                    line-height: 1.6;
                }
                .footnotes {
                    margin-top: 3em;
                    font-size: 0.9em;
                    border-top: 1px solid #cccccc;
                    padding-top: 1em;
                }
                .footnote {
                    margin: 0.5em 0;
                    font-size: 0.9em;
                }
                .chapter-notes {
                    margin-top: 3em;
                    padding-top: 1em;
                    border-top: 1px solid #ccc;
                    font-size: 0.9em;
                }
                .note {
                    font-style: italic;
                    margin: 0.5em 0;
                }
                sup {
                    vertical-align: super;
                    font-size: 0.8em;
                }
                a {
                    color: #000000;
                    text-decoration: none;
                }
